package oracle;
import java.util.*;import java.io.*;import org.json.simple.*;import org.json.simple.parser.JSONParser;import core.game.node.entity.npc.NPC;import core.game.node.entity.player.Player;import core.game.world.map.Location;import core.game.interaction.MovementPulse;import core.tools.RandomFunction;
public class Support{
 static Map input;static NPC npc;static List<Object>events;static Map<String,Integer>calls;public static int worldTicks,impact,nextPulse;public static Location pendingTeleport;
 public static class Failure extends RuntimeException{}
 static class Rng extends Random{Rng(long seed){super(seed);}@Override public boolean nextBoolean(){boolean b=super.nextBoolean();emit("Bool",b);return b;}@Override public int nextInt(int bound){int n=super.nextInt(bound);emit("Int",bound,n);return n;}}
 static int n(Object o){return((Number)o).intValue();}static int v(Map m,String k,int d){return m.get(k)==null?d:n(m.get(k));}static boolean b(Map m,String k){return Boolean.TRUE.equals(m.get(k));}static Location loc(Object o){if(o==null)return null;List a=(List)o;return Location.create(n(a.get(0)),n(a.get(1)),n(a.get(2)));}public static Object coord(Location l){return l==null?null:Arrays.asList(l.getX(),l.getY(),l.getZ());}
 public static void emit(String phase,Object...args){List row=new ArrayList();row.add(phase);row.addAll(Arrays.asList(args));events.add(row);int at=calls.merge(phase,1,Integer::sum);for(Object o:(List)input.getOrDefault("hooks",Collections.emptyList())){Map h=(Map)o;if(phase.equals(h.get("event"))&&at==v(h,"at",1))for(Object a:(List)h.get("actions"))act((Map)a);}if(at==v((Map)input.getOrDefault("failures",Collections.emptyMap()),phase,-1))throw new Failure();}
 public static boolean query(String phase,boolean fallback,Object...args){emit(phase,args);Object value=((Map)input.getOrDefault("answers",Collections.emptyMap())).get(phase);if(value instanceof List){List a=(List)value;int i=calls.get(phase)-1;return i<a.size()?Boolean.TRUE.equals(a.get(i)):fallback;}return value==null?fallback:Boolean.TRUE.equals(value);}
 public static int ticks(){int result=worldTicks;emit("Ticks",result);return result;}
 static void set(Map m){if(m.containsKey("location"))npc.location=loc(m.get("location"));if(m.containsKey("spawn"))npc.props.spawnLocation=loc(m.get("spawn"));if(m.containsKey("radius"))npc.walkRadius=v(m,"radius",11);if(m.containsKey("walks"))npc.walks=b(m,"walks");if(m.containsKey("pathBound"))npc.pathBoundMovement=b(m,"pathBound");if(m.containsKey("path")){List path=(List)m.get("path");if(path==null)npc.movementPath=null;else{npc.movementPath=new Location[path.size()];for(int i=0;i<path.size();i++)npc.movementPath[i]=loc(path.get(i));}}if(m.containsKey("pathIndex"))npc.movementIndex=v(m,"pathIndex",0);if(m.containsKey("nextWalk"))npc.nextWalk=v(m,"nextWalk",0);if(m.containsKey("aggressive"))npc.aggressive=b(m,"aggressive");if(m.containsKey("handler"))npc.aggressiveHandler=b(m,"handler")?new NPC.Aggression():null;if(m.containsKey("neverWalks"))npc.neverWalks=b(m,"neverWalks");if(m.containsKey("noReturn"))npc.attributes.put("no-spawn-return",b(m,"noReturn"));if(m.containsKey("returning"))npc.attributes.put("return-to-spawn",b(m,"returning"));if(m.containsKey("returnPulse")){Object p=m.get("returnPulse");if(p==null)npc.attributes.remove("return-to-spawn-pulse");else npc.attributes.put("return-to-spawn-pulse",new MovementPulse(n(p)));}if(m.containsKey("dialogue"))npc.dialoguePlayer=m.get("dialogue")==null?null:new Player(n(m.get("dialogue")));if(m.containsKey("forceTalk"))npc.forceTalk=(String)m.get("forceTalk");if(m.containsKey("lastTalk"))npc.attributes.put("lastForceTalk",v(m,"lastTalk",0));if(m.containsKey("respawn"))npc.respawnTick=v(m,"respawn",-1);if(m.containsKey("respawning"))npc.isRespawning=b(m,"respawning");}
 static Object act(Map a){switch((String)a.get("op")){case"tick":npc.tick();break;case"actions":npc.handleTickActions();break;case"destination":return coord(npc.destination());case"setNext":npc.setNextWalk();break;case"arrival":return((MovementPulse)npc.attributes.get("return-to-spawn-pulse")).pulse();case"advance":worldTicks+=v(a,"ticks",1);break;case"set":set((Map)a.get("fields"));break;default:throw new AssertionError(a);}return null;}
 static Map state(Object result,String error){Map m=new TreeMap();List path=null;if(npc.movementPath!=null){path=new ArrayList();for(Location l:npc.movementPath)path.add(coord(l));}MovementPulse pulse=(MovementPulse)npc.attributes.get("return-to-spawn-pulse");m.put("location",coord(npc.location));m.put("spawn",coord(npc.props.spawnLocation));m.put("radius",npc.walkRadius);m.put("walks",npc.walks);m.put("pathBound",npc.pathBoundMovement);m.put("path",path);m.put("pathIndex",npc.movementIndex);m.put("nextWalk",npc.nextWalk);m.put("aggressive",npc.aggressive);m.put("handler",npc.aggressiveHandler!=null);m.put("pause",npc.aggressiveHandler==null?null:npc.aggressiveHandler.pause);m.put("neverWalks",npc.neverWalks);m.put("noReturn",npc.attributes.getOrDefault("no-spawn-return",false));m.put("returnPulse",pulse==null?null:pulse.id);m.put("returning",npc.attributes.getOrDefault("return-to-spawn",false));m.put("dialogue",npc.dialoguePlayer==null?null:npc.dialoguePlayer.id);m.put("forceTalk",npc.forceTalk);m.put("lastTalk",npc.attributes.getOrDefault("lastForceTalk",0));m.put("respawn",npc.respawnTick);m.put("respawning",npc.isRespawning);m.put("locked",npc.movementLocked);m.put("impact",impact);m.put("pendingTeleport",coord(pendingTeleport));m.put("ticks",worldTicks);m.put("nextPulse",nextPulse);m.put("events",new ArrayList<>(events));m.put("result",result);m.put("error",error);return m;}
 public static void main(String[]args)throws Exception{try(BufferedReader r=new BufferedReader(new InputStreamReader(System.in,java.nio.charset.StandardCharsets.UTF_8))){String line;while((line=r.readLine())!=null){input=(Map)new JSONParser().parse(line);events=new ArrayList<>();calls=new HashMap<>();worldTicks=v(input,"ticks",100);impact=nextPulse=0;pendingTeleport=null;RandomFunction.RANDOM=new Rng(((Number)input.getOrDefault("seed",0L)).longValue());npc=new NPC();set((Map)input.get("fields"));List out=new ArrayList();for(Object a:(List)input.get("actions")){events.clear();Object result=null;String error=null;try{result=act((Map)a);}catch(Throwable e){error=e instanceof NullPointerException?"Null":e instanceof IndexOutOfBoundsException?"Index":e instanceof Failure?"Binding":e.getClass().getSimpleName();}out.add(state(result,error));}input.put("expected",out);System.out.println(JSONValue.toJSONString(input));}}}
}
